using System;using System.IO;using IdleIntelligence.Core;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 [Serializable]public sealed class NarrativeCase{public string op,value;public bool hasName,legacyChapters;public StoryState before,after;public StoryFacts beforeFacts,facts;}
 [Serializable]public sealed class NarrativeCases{public NarrativeCase[] rows;}
 public sealed class NarrativeTests {
 [Test]public void EverySourceDialogueTransitionMatches(){var cases=JsonUtility.FromJson<NarrativeCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/NarrativeReferenceCases.json")));Assert.That(cases.rows.Length,Is.EqualTo(452));int index=0;foreach(var c in cases.rows){c.before=StoryState.Restore(c.before);if(c.legacyChapters)c.before.chapters=null;StoryState actual=c.before;string original=JsonUtility.ToJson(c.before);switch(c.op){case "name":actual=NarrativeRules.ChooseName(c.before,c.hasName,c.value);break;case "continue":actual=NarrativeRules.Continue(c.before,c.facts);break;case "skip":actual=NarrativeRules.SkipCurrent(c.before);break;case "skip-tutorial":actual=NarrativeRules.SkipTutorial(c.before);break;case "resume":actual=NarrativeRules.Resume(c.before);break;case "reopen":actual=NarrativeRules.Reopen(c.before,c.value);break;case "chapter":actual=NarrativeRules.ReopenChapter(c.before,c.value);break;case "toggle":actual=NarrativeRules.Toggle(c.before);break;case "advance":actual=NarrativeRules.Advance(c.before,c.facts);break;case "prepare":actual=NarrativeRules.Prepare(c.before,c.facts);break;case "sync":actual=NarrativeRules.Sync(c.before,c.beforeFacts,c.facts);break;default:Assert.Fail(c.op);break;}Assert.That(JsonUtility.ToJson(actual),Is.EqualTo(JsonUtility.ToJson(c.after)),index+" "+c.op+" "+c.value);Assert.That(JsonUtility.ToJson(c.before),Is.EqualTo(original),"mutated input "+index);try{NarrativeRules.Validate(actual);}catch(Exception e){Assert.Fail(index+" "+c.op+" "+JsonUtility.ToJson(actual)+" "+e.Message);}index++;}}
 }
}
